typedef unsigned int u_int;
#define NULL 0

class nglFixedString
{
  char Data[32];
};

struct nglTexture;
struct nglMaterialInfo
{
  u_int Hash;
  u_int DiffuseKickAddr;
  u_int DetailKickAddr;
  u_int EnvironmentKickAddr;
  u_int LightKickAddr;
  u_int CmdListEndAddr;
  u_int* BakedDMA;
};

struct nglMaterial
{
  u_int Flags;
  nglTexture* Map;
  nglTexture* LightMap;
  nglTexture* DetailMap;
  nglTexture* EnvironmentMap;
  char Data[216];
  nglMaterialInfo* Info;
};

struct nglMeshSection
{
  nglMaterial* Material;
  char Data[60];
};

struct nglMesh
{
  u_int Flags;
  void* File;
  nglMesh* NextMesh;
  u_int DataSize;
  nglFixedString Name;
  char Data[36];
  u_int NSections;
  nglMeshSection* Sections;
  u_int Pad;
};

struct nglFileBuf
{
  void* Buf;
  u_int Size;
  u_int UserData;
};

struct nglMeshFile
{
  nglFixedString FileName;
  char FilePath[256];
  nglFileBuf FileBuf;
  bool LoadedInPlace;
  nglMesh* FirstMesh;
};

class nglInstanceBank
{
public:
  struct Instance
  {
    nglFixedString Key;
    void* Value;
    int RefCount;
    Instance* Forward[1];
  };

  int Delete( const nglFixedString& Key );
  Instance* Search( const nglFixedString& Key );
};

enum
{
  NGLMAT_TEXTURE_MAP = 0x00000010,
  NGLMAT_LIGHT_MAP = 0x00000020,
  NGLMAT_DETAIL_MAP = 0x00000040,
  NGLMAT_ENVIRONMENT_MAP = 0x00000080,
};

extern nglInstanceBank nglMeshFileBank;
extern nglInstanceBank nglMeshBank;
void nglVif1SafeWait();
void nglReleaseTexture( nglTexture* Tex );
void nglMemFree( void* Ptr );
void nglReleaseFile( nglFileBuf* File );

__asm__(".equ nglMeshFileBank, 0x004BBFE0");
__asm__(".equ nglMeshBank, 0x004BBFC8");
__asm__(".equ nglVif1SafeWait__Fv, 0x00397728");
__asm__(".equ Search__15nglInstanceBankRC14nglFixedString, 0x003AC608");
__asm__(".equ Delete__15nglInstanceBankRC14nglFixedString, 0x003AC440");
__asm__(".equ nglReleaseTexture__FP10nglTexture, 0x0039C820");
__asm__(".equ nglMemFree__FPv, 0x00395D50");
__asm__(".equ nglReleaseFile__FP10nglFileBuf, 0x00395CB8");

void nglReleaseMeshFile( const nglFixedString& FileName )
{
  // Make sure they don't try and destroy it while it's being rendered from.
  nglVif1SafeWait();

  // Remove a reference from the instance bank, delete the mesh file only if the count hits 0.
  nglInstanceBank::Instance* Inst = nglMeshFileBank.Search( FileName );
  if ( !Inst )
    return;
  if ( --Inst->RefCount > 0 )
    return;

  nglMeshFile* MeshFile = (nglMeshFile*)Inst->Value;
  nglMeshFileBank.Delete( MeshFile->FileName );

  nglMesh* Mesh = MeshFile->FirstMesh;
  while ( Mesh )
  {
    for ( u_int i = 0; i < Mesh->NSections; i++ )
    {
      nglMaterial* Material = Mesh->Sections[i].Material;
      if ( Material->Flags & NGLMAT_TEXTURE_MAP )
        nglReleaseTexture( Material->Map );

      if ( Material->Flags & NGLMAT_LIGHT_MAP )
        nglReleaseTexture( Material->LightMap );

      if ( Material->Flags & NGLMAT_DETAIL_MAP )
        nglReleaseTexture( Material->DetailMap );

      if ( Material->Flags & NGLMAT_ENVIRONMENT_MAP )
        nglReleaseTexture( Material->EnvironmentMap );

      nglMemFree( Material->Info->BakedDMA );
      nglMemFree( Material->Info );
	  Material->Info = NULL;
    }

    nglMeshBank.Delete( Mesh->Name );
    Mesh = Mesh->NextMesh;
  }

  if ( !MeshFile->LoadedInPlace )
    nglReleaseFile( &MeshFile->FileBuf );

  nglMemFree( MeshFile );
}
